U.add('snd','elevator',{sev:.2,play:(a,o,r)=>{const n=a.createBufferSource(),b=a.createBuffer(1,a.sampleRate*2,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;n.buffer=b;n.loop=true;const f=a.createBiquadFilter(),g=a.createGain();f.type='lowpass';f.frequency.value=120+r(300)*180;g.gain.value=.25;n.connect(f).connect(g).connect(o);n.start();const p=600+r(301)*400,q=.75+r(302)*.09,ty=r(303)<.6?'sine':'triangle',pr=.2+r(304)*.5,t=setInterval(()=>{if(Math.random()>pr)return;[0,.45].forEach((dl,k)=>{const x=a.createOscillator(),e=a.createGain(),s=a.currentTime+dl;x.type=ty;x.frequency.value=k?p*q:p;e.gain.setValueAtTime(.15,s);e.gain.exponentialRampToValueAtTime(.001,s+1.5);x.connect(e).connect(o);x.start(s);x.stop(s+1.6)})},2000+r(305)*3000);return()=>{clearInterval(t);n.stop()}}});
