U.add('snd','muzak',{sev:0,play:(a,o,r)=>{const b=180*Math.pow(2,Math.floor(r(300)*12)/12),P=[[[0,4,7,11],[5,9,12,16],[2,5,9,12],[7,11,14,17]],[[0,3,7,10],[5,8,12,15],[7,10,14,17],[3,7,10,14]],[[0,4,7,9],[9,12,16,19],[5,9,12,16],[7,11,14,17]]],ch=P[Math.floor(r(301)*3)],ty=['triangle','sine','square'][Math.floor(r(303)*3)],nv=3+Math.floor(r(305)*2),f=a.createBiquadFilter();f.type='lowpass';f.frequency.value=500+r(304)*2500;f.connect(o);let i=0;const v=[...Array(nv)].map(()=>{const x=a.createOscillator(),g=a.createGain();x.type=ty;g.gain.value=ty=='square'?.05:.12;x.connect(g).connect(f);x.start();return x});const step=()=>{ch[i++%4].slice(0,nv).forEach((s,k)=>v[k].frequency.setTargetAtTime(b*Math.pow(2,s/12),a.currentTime,.05))};step();const t=setInterval(step,1400+r(302)*2400);return()=>{clearInterval(t);v.forEach(x=>x.stop())}}});
